        local fetch,toPtr=rawget(g,'EEex_Resource_Fetch'),rawget(g,'EEex_UDToPtr')
        if not read or type(fetch)~='function' or type(toPtr)~='function' then
            problem('EEex resource access unavailable');return nil
        end
