                local ids=g.EEex_Resource_LoadIDS('PROJECTL')
                g.EEex_Resource_IterateUnpackedIDSEntries(ids,function(id,line,start)
                    local name=type(start)=='string' and start:match('^%s*(%S+)') or
                        type(line)=='string' and line:match('^%s*(%S+)')
